function validate([blocked, source, target]) {
  const N = 1000000;
  const cell = p => Array.isArray(p) && p.length === 2 && p.every(v => Number.isInteger(v) && v >= 0 && v < N);
  if (!Array.isArray(blocked) || blocked.length > 200) return 'blocked has at most 200 cells.';
  if (!blocked.every(cell)) return 'Every blocked cell is [x, y] with 0 <= x, y < 10^6.';
  if (!cell(source) || !cell(target)) return 'source and target are [x, y] with 0 <= x, y < 10^6.';
  if (source[0] === target[0] && source[1] === target[1]) return 'source and target must be different cells.';
  if (blocked.some(([x, y]) => (x === source[0] && y === source[1]) || (x === target[0] && y === target[1]))) return 'source and target cannot be blocked.';
  return null;
}

