function isEscapePossible(blocked, source, target) {
  const SIZE = 1000000;
  const walls = new Set();
  for (const [x, y] of blocked) {
    walls.add(x * SIZE + y);
  }
  const limit = blocked.length * (blocked.length - 1) / 2;
  const moves = [[1, 0], [-1, 0], [0, 1], [0, -1]];

  const canLeave = (start, goal) => {
    const seen = new Set([start[0] * SIZE + start[1]]);
    const queue = [start];
    let head = 0;
    while (head < queue.length) {
      const [x, y] = queue[head++];
      if (x === goal[0] && y === goal[1]) {
        return true;
      }
      if (seen.size > limit) {
        return true;
      }
      for (const [dx, dy] of moves) {
        const nx = x + dx;
        const ny = y + dy;
        const key = nx * SIZE + ny;
        if (nx < 0 || ny < 0 || nx >= SIZE || ny >= SIZE) {
          continue;
        }
        if (walls.has(key) || seen.has(key)) {
          continue;
        }
        seen.add(key);
        queue.push([nx, ny]);
      }
    }
    return false;
  };

  return canLeave(source, target) && canLeave(target, source);
}

