function isEscapePossible(blocked, source, target) {
  // Coordinate compression: runs of rows (or columns) holding no wall, source or target are
  // completely open, so each run can shrink to a single row without changing connectivity.
  const N = 1000000;
  const axis = k => {
    const values = new Set([0, N - 1]);
    for (const p of [...blocked, source, target]) for (const d of [-1, 0, 1]) if (p[k] + d >= 0 && p[k] + d < N) values.add(p[k] + d);
    const sorted = [...values].sort((a, b) => a - b);
    const index = new Map();
    let next = 0;
    sorted.forEach((v, i) => { if (i > 0 && v > sorted[i - 1] + 1) next++; index.set(v, next++); });
    return [index, next];
  };
  const [rows, width] = axis(0), [cols, height] = axis(1);
  const open = Array.from({ length: width }, () => new Array(height).fill(true));
  for (const [x, y] of blocked) open[rows.get(x)][cols.get(y)] = false;
  const sx = rows.get(source[0]), sy = cols.get(source[1]), tx = rows.get(target[0]), ty = cols.get(target[1]);
  const stack = [[sx, sy]];
  open[sx][sy] = false;
  while (stack.length) {
    const [x, y] = stack.pop();
    if (x === tx && y === ty) return true;
    for (const [nx, ny] of [[x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]]) {
      if (nx >= 0 && ny >= 0 && nx < width && ny < height && open[nx][ny]) { open[nx][ny] = false; stack.push([nx, ny]); }
    }
  }
  return false;
}

