function generate(rand, size) {
  const N = 1000000;
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const budget = size === 'large' ? 200 : int(0, 12);
  // A shape is a barrier of walls at "level" r around an inner region of lower levels, placed
  // in a corner, against an edge, or anywhere as a diamond. Too small a share gives scattered walls.
  const makeShape = share => {
    const kind = share >= 4 && rand() < 0.4 ? 'diamond' : share >= 3 && rand() < 0.4 ? 'edge' : share >= 1 ? 'corner' : 'none';
    const flipX = rand() < 0.5, flipY = rand() < 0.5, swap = rand() < 0.5;
    let r, level, inRegion, place;
    if (kind === 'corner' || kind === 'none') {
      r = Math.max(0, int(Math.max(1, Math.floor(share / 2)), Math.max(1, share)) - 1);
      level = (u, v) => u + v;
      inRegion = (u, v) => u >= 0 && v >= 0;
      place = (u, v) => [flipX ? N - 1 - u : u, flipY ? N - 1 - v : v];
    } else if (kind === 'edge') {
      r = int(1, Math.floor((share - 1) / 2));
      const middle = rand() < 0.3 ? int(r + 1, r + 4) : int(r + 1, N - r - 2);
      level = (u, v) => u + Math.abs(v);
      inRegion = u => u >= 0;
      place = (u, v) => [flipX ? N - 1 - u : u, middle + v];
    } else {
      r = int(1, Math.floor(share / 4));
      const cx = rand() < 0.3 ? int(r + 1, r + 3) : int(r + 1, N - r - 2), cy = int(r + 1, N - r - 2);
      level = (u, v) => Math.abs(u) + Math.abs(v);
      inRegion = () => true;
      place = (u, v) => [cx + u, cy + v];
    }
    const orient = ([x, y]) => (swap ? [y, x] : [x, y]);
    const barrier = [];
    if (kind !== 'none') {
      for (let u = -r; u <= r; u++) for (const v of new Set([r - Math.abs(u), Math.abs(u) - r])) if (inRegion(u, v)) barrier.push(orient(place(u, v)));
    }
    const pick = wantInside => {
      for (let tries = 0; tries < 50; tries++) {
        const u = int(-r - 3, r + 3), v = int(-r - 3, r + 3);
        if (!inRegion(u, v)) continue;
        const [x, y] = place(u, v);
        if (x < 0 || y < 0 || x >= N || y >= N) continue;
        if (wantInside ? level(u, v) < r : level(u, v) > r) return orient([x, y]);
      }
      return orient(place(r + 1, 0));
    };
    return { barrier, pick, hasInside: kind !== 'none' && r > 0 };
  };
  for (;;) {
    const twoShapes = budget >= 4 && rand() < 0.35;
    const first = makeShape(twoShapes ? Math.floor(budget / 2) : budget);
    const second = twoShapes ? makeShape(budget - Math.floor(budget / 2)) : first;
    const walls = new Map();
    const add = ([x, y]) => { if (x >= 0 && y >= 0 && x < N && y < N && walls.size < budget) walls.set(x * N + y, [x, y]); };
    first.barrier.forEach(add);
    if (twoShapes) second.barrier.forEach(add);
    // Sometimes open a gap in the barrier.
    if (walls.size > 0 && rand() < 0.25) walls.delete([...walls.keys()][int(0, walls.size - 1)]);
    // Fill any spare budget with walls scattered near a shape.
    const anchor = first.pick(rand() < 0.5);
    while (walls.size < budget && rand() < 0.8) add([anchor[0] + int(-6, 6), anchor[1] + int(-6, 6)]);
    const far = () => (rand() < 0.5 ? [int(0, N - 1), int(0, N - 1)] : [rand() < 0.5 ? 0 : N - 1, int(0, N - 1)]);
    const choose = shape => {
      const r = rand();
      if (shape.hasInside && r < 0.5) return shape.pick(true);
      if (r < 0.8) return shape.pick(false);
      return far();
    };
    const source = choose(first);
    const target = rand() < 0.3 ? choose(first) : choose(second);
    if (source[0] === target[0] && source[1] === target[1]) continue;
    if (walls.has(source[0] * N + source[1]) || walls.has(target[0] * N + target[1])) continue;
    return [[...walls.values()], source, target];
  }
}
